"""Triton implementation of ``aten::unique_dim_consecutive``.

Semantics (verified against the target's torch 2.9 aten kernel):
  each *slice* along ``dim`` (the whole sub-tensor with ``dim`` removed) is one
  atomic element, so with ``L = shape[dim]`` and ``M = numel / L`` the problem is
  "collapse adjacent equal rows" on the logical ``(L, M)`` matrix:
    out            : input shape with ``shape[dim] -> K`` (K = number of runs)
    inverse_indices: int64, 1-D of length ``L`` (run rank of every slice)
    counts         : int64, 1-D of length ``K`` (run lengths)
  ``inverse_indices`` / ``counts`` are empty (numel 0) when their flag is false.

Pipeline: (1) per-slice "new run" flags, (2) prefix scan -> ranks + K,
(3) run-start positions by binary search on the monotone rank array,
(4) gather of run-start rows into ``out``, (5) run lengths.

Backend notes (measured on P800/flagtree): masked loads do not reliably apply
``other`` and masked *scatter* stores return wrong data, so addresses are
clamped to stay in bounds, semantics are applied with ``tl.where`` / masked
linear stores, and compaction is done by search instead of scatter.
"""

import torch
import triton
import triton.language as tl


@triton.jit
def _rowdiff_kernel(
    x_ptr,
    y_ptr,
    d_ptr,
    L,
    M,
    STORE: tl.constexpr,
    BLOCK_T: tl.constexpr,
    BLOCK_M: tl.constexpr,
):
    """Fused diff + speculative copy for the contiguous dim==0 layout, where the
    input and out have identical flat layout (row t of both lives at t * M).

    Each CTA owns BLOCK_T slices, loads each one once, compares it with its
    predecessor, and (when STORE) writes it to out[t] while it is still in
    registers. Waiting until the run count is known would need a second read of
    the whole input, so instead out is allocated with all L rows up front and the
    host keeps it only when every slice turns out to start a run (K == L).
    The row reduction stays outside the inner loop: this backend miscompiles
    reductions placed inside a loop."""
    ts = tl.program_id(0) * BLOCK_T + tl.arange(0, BLOCK_T)
    tmask = ts < L
    p_ts = tl.maximum(ts - 1, 0)
    es = tl.arange(0, BLOCK_M)
    acc = tl.zeros((BLOCK_T, BLOCK_M), dtype=tl.int32)
    for m0 in range(0, M, BLOCK_M):
        e = m0 + es
        m = tmask[:, None] & (e < M)[None, :]
        cur = tl.load(x_ptr + ts[:, None] * M + e[None, :], mask=m, other=0)
        prv = tl.load(x_ptr + p_ts[:, None] * M + e[None, :], mask=m, other=0)
        acc += tl.where(m & (ts[:, None] > 0), (cur != prv).to(tl.int32), 0)
        if STORE:
            tl.store(y_ptr + ts[:, None] * M + e[None, :], cur, mask=m)
    n = tl.sum(acc, axis=1)
    new = tl.where(ts == 0, 1, (n > 0).to(tl.int32))
    tl.store(d_ptr + ts, new, mask=tmask)


@triton.jit
def _rowdiff_general_kernel(
    x_ptr,
    d_ptr,
    L,
    M,
    inner_size,
    sd,
    S_hi,
    unit,
    HAS_OUTER: tl.constexpr,
    BLOCK_T: tl.constexpr,
    BLOCK_M: tl.constexpr,
):
    ts = tl.program_id(0) * BLOCK_T + tl.arange(0, BLOCK_T)
    tmask = ts < L
    p_ts = tl.maximum(ts - 1, 0)
    es = tl.arange(0, BLOCK_M)
    acc = tl.zeros((BLOCK_T, BLOCK_M), dtype=tl.int32)
    for e0 in range(0, M, BLOCK_M):
        e = e0 + es
        ec = tl.minimum(e, M - 1)
        if HAS_OUTER:
            base = (ec // inner_size) * S_hi + (ec % inner_size) * unit
        else:
            base = ec * unit
        m = tmask[:, None] & (e < M)[None, :]
        cur = tl.load(x_ptr + ts[:, None] * sd + base[None, :], mask=m, other=0)
        prv = tl.load(x_ptr + p_ts[:, None] * sd + base[None, :], mask=m, other=0)
        acc += tl.where(m & (ts[:, None] > 0), (cur != prv).to(tl.int32), 0)
    n = tl.sum(acc, axis=1)
    new = tl.where(ts == 0, 1, (n > 0).to(tl.int32))
    tl.store(d_ptr + ts, new, mask=tmask)


@triton.jit
def _scan_kernel(d_ptr, inv_ptr, k_ptr, L, BLOCK: tl.constexpr):
    ts = tl.arange(0, BLOCK)
    mask = ts < L
    d = tl.where(mask, tl.load(d_ptr + tl.minimum(ts, L - 1), mask=mask, other=0), 0)
    tl.store(inv_ptr + ts, (tl.cumsum(d, axis=0) - 1).to(tl.int64), mask=mask)
    tl.store(k_ptr, tl.sum(d, axis=0))


@triton.jit
def _chunk_sum_kernel(d_ptr, sums_ptr, L, BLOCK: tl.constexpr):
    ts = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = ts < L
    d = tl.where(mask, tl.load(d_ptr + tl.minimum(ts, L - 1), mask=mask, other=0), 0)
    tl.store(sums_ptr + tl.program_id(0), tl.sum(d, axis=0))


@triton.jit
def _chunk_off_kernel(sums_ptr, off_ptr, k_ptr, nchunks, BLOCK_C: tl.constexpr):
    cs = tl.arange(0, BLOCK_C)
    mask = cs < nchunks
    s = tl.where(
        mask, tl.load(sums_ptr + tl.minimum(cs, nchunks - 1), mask=mask, other=0), 0
    )
    tl.store(off_ptr + cs, tl.cumsum(s, axis=0) - s, mask=mask)
    tl.store(k_ptr, tl.sum(s, axis=0))


@triton.jit
def _chunk_rank_kernel(d_ptr, off_ptr, inv_ptr, L, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    ts = pid * BLOCK + tl.arange(0, BLOCK)
    mask = ts < L
    d = tl.where(mask, tl.load(d_ptr + tl.minimum(ts, L - 1), mask=mask, other=0), 0)
    rank = tl.load(off_ptr + pid) + tl.cumsum(d, axis=0) - 1
    tl.store(inv_ptr + ts, rank.to(tl.int64), mask=mask)


@triton.jit
def _first_pos_kernel(inv_ptr, first_ptr, L, K, steps, BLOCK_J: tl.constexpr):
    """first[j] = min{t : rank[t] == j}; rank is non-decreasing, so this is a
    binary search for the first index whose rank is >= j (scatter-free).
    ``steps`` is a runtime value on purpose: a constant trip count makes the
    backend loop-unroll pass miscompile this reduction."""
    js = tl.program_id(0) * BLOCK_J + tl.arange(0, BLOCK_J)
    lo = tl.zeros((BLOCK_J,), dtype=tl.int32)
    hi = tl.full((BLOCK_J,), L - 1, dtype=tl.int32)
    target = js.to(tl.int64)
    i = 0
    # while-loop: the backend's scf.for unroll pass miscompiles this reduction
    while i < steps:
        mid = (lo + hi) // 2
        v = tl.load(inv_ptr + mid)
        ge = v >= target
        lo = tl.where(ge, lo, mid + 1)
        hi = tl.where(ge, mid, hi)
        i += 1
    tl.store(first_ptr + js, lo, mask=js < K)


@triton.jit
def _gather_kernel(
    x_ptr,
    out_ptr,
    first_ptr,
    K,
    M,
    inner_size,
    sd,
    S_hi,
    unit,
    so_d,
    S_hi_o,
    HAS_OUTER: tl.constexpr,
    BLOCK_J: tl.constexpr,
    BLOCK_M: tl.constexpr,
):
    """Copy the K run-start rows into out. One CTA owns BLOCK_J rows and
    streams the whole row with an inner loop so the single dependent first[]
    load (and the CTA launch) is amortized over tens of KB."""
    js = tl.program_id(0) * BLOCK_J + tl.arange(0, BLOCK_J)
    jm = js < K
    jc = tl.minimum(js, K - 1)
    src_t = tl.load(first_ptr + jc)
    es = tl.arange(0, BLOCK_M)
    for m0 in range(0, M, BLOCK_M):
        e = m0 + es
        ec = tl.minimum(e, M - 1)
        if HAS_OUTER:
            sbase = (ec // inner_size) * S_hi + (ec % inner_size) * unit
            dbase = (ec // inner_size) * S_hi_o + (ec % inner_size)
        else:
            sbase = ec * unit
            dbase = ec
        src = src_t[:, None] * sd + sbase[None, :]
        dst = jc[:, None] * so_d + dbase[None, :]
        m = jm[:, None] & (e < M)[None, :]
        tl.store(out_ptr + dst, tl.load(x_ptr + src, mask=m, other=0), mask=m)


@triton.jit
def _counts_kernel(first_ptr, cnt_ptr, K, L, BLOCK: tl.constexpr):
    js = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = js < K
    jc = tl.minimum(js, K - 1)
    a = tl.load(first_ptr + jc)
    b = tl.where(js + 1 < K, tl.load(first_ptr + tl.minimum(js + 1, K - 1)), L)
    tl.store(cnt_ptr + js, (b - a).to(tl.int64), mask=mask)


_SCAN_BLOCK = 4096
_MAX_TILE = 1024
_COPY_BLOCK = 4096
_ROW_TILE = 8


def _row_tiles(M):
    """(BLOCK_T, BLOCK_M) with a ~1024-element tile so that short rows still
    load coalesced across neighbouring rows."""
    if M <= 0:
        return 1, 1
    bm = min(triton.next_power_of_2(M), _MAX_TILE)
    return max(1, _MAX_TILE // bm), bm


def unique_dim_consecutive(input, dim, return_inverse=False, return_counts=False):
    x = input
    nd = x.dim()
    if nd == 0:
        x = x.view(1)
        nd = 1
    d = int(dim)
    if d < 0:
        d += nd
    if d < 0 or d >= nd:
        raise IndexError(
            "Dimension out of range (expected to be in range of [{}, {}], but got {})".format(
                -nd, nd - 1, dim
            )
        )

    shape = list(x.shape)
    L = int(shape[d])
    numel = int(x.numel())
    dev = x.device

    if numel == 0 or L == 0:
        out_shape = list(shape)
        out_shape[d] = 0
        return (
            torch.empty(out_shape, dtype=x.dtype, device=dev),
            torch.empty(0, dtype=torch.int64, device=dev),
            torch.empty(0, dtype=torch.int64, device=dev),
        )

    M = numel // L
    inner_size = 1
    for s in shape[d + 1 :]:
        inner_size *= int(s)
    outer_size = numel // (L * inner_size) if (L * inner_size) else 0

    if x.dtype == torch.bool:
        x = x.view(torch.uint8)
    if x.is_contiguous():
        unit, sd = 1, inner_size
    else:
        strides = x.stride()
        unit = int(strides[-1]) if nd > 1 else 1
        rstride = inner_size * unit
        acc, ok = 1, True
        for k in range(nd - 1, d, -1):
            ok = ok and int(strides[k]) == acc
            acc *= int(shape[k])
        sd = int(strides[d])
        ok = ok and sd == rstride
        hi = 1
        for k in range(d - 1, -1, -1):
            ok = ok and int(strides[k]) == hi * L * rstride
            hi *= int(shape[k])
        if not ok:
            raise NotImplementedError(
                "unique_dim_consecutive: unsupported non-contiguous layout"
            )
    S_hi = L * inner_size * unit

    # ---- stage 1: per-slice "new run" flags -------------------------------
    # For the contiguous dim==0 layout the input and out share one flat layout,
    # so the diff kernel also copies each row into a speculative out buffer while
    # the row is in registers; the host keeps that buffer when K turns out to
    # equal L, which removes the whole separate copy pass.
    d_buf = torch.empty(L, dtype=torch.int32, device=dev)
    bm = min(triton.next_power_of_2(M), _MAX_TILE)
    # Prefer _ROW_TILE rows per CTA while keeping the tile at 4096 elements:
    # halve the chunk width when the rows are too wide to fit that many.
    bt = max(1, min(_ROW_TILE, 4096 // bm))
    while bt < _ROW_TILE and bm > 64:
        bm //= 2
        bt = max(1, min(_ROW_TILE, 4096 // bm))
    spec = None
    if d == 0 and x.is_contiguous() and M > 0:
        spec = torch.empty((L,) + tuple(shape[1:]), dtype=x.dtype, device=dev)
        _rowdiff_kernel[(triton.cdiv(L, bt),)](
            x, spec, d_buf, L, M, STORE=True, BLOCK_T=bt, BLOCK_M=bm, num_warps=8
        )
    else:
        bt = max(1, _MAX_TILE // bm)
        _rowdiff_general_kernel[(triton.cdiv(L, bt),)](
            x,
            d_buf,
            L,
            M,
            inner_size,
            sd,
            S_hi,
            unit,
            HAS_OUTER=outer_size > 1,
            BLOCK_T=bt,
            BLOCK_M=bm,
            num_warps=4,
        )

    # ---- stage 2: prefix scan -> ranks, K --------------------------------
    inv_buf = torch.empty(L, dtype=torch.int64, device=dev)
    k_buf = torch.empty(1, dtype=torch.int32, device=dev)
    if L <= _SCAN_BLOCK:
        blk = max(triton.next_power_of_2(L), 1)
        _scan_kernel[(1,)](
            d_buf, inv_buf, k_buf, L, BLOCK=blk, num_warps=8 if blk >= 1024 else 4
        )
    else:
        nch = triton.cdiv(L, _SCAN_BLOCK)
        sums = torch.empty(nch, dtype=torch.int32, device=dev)
        offs = torch.empty(nch, dtype=torch.int32, device=dev)
        _chunk_sum_kernel[(nch,)](d_buf, sums, L, BLOCK=_SCAN_BLOCK, num_warps=8)
        _chunk_off_kernel[(1,)](
            sums, offs, k_buf, nch, BLOCK_C=triton.next_power_of_2(nch), num_warps=8
        )
        _chunk_rank_kernel[(nch,)](
            d_buf, offs, inv_buf, L, BLOCK=_SCAN_BLOCK, num_warps=8
        )

    K = int(k_buf.item())

    # Speculative buffer already holds the answer when every slice starts a run.
    identity = (K == L) and spec is not None

    # ---- stage 3: run-start positions ------------------------------------
    # Needed for the gather, and for counts (which reads first[]); the identity
    # path can skip it when counts were not requested.
    first = torch.empty(max(K, 1), dtype=torch.int32, device=dev)
    if K > 0 and (not identity or return_counts):
        # 64 lanes: larger blocks make the backend assign conflicting core
        # tilings to the loop-carried tensors of the search kernel.
        bj = 64
        steps = max(1, int(L).bit_length())
        _first_pos_kernel[(triton.cdiv(K, bj),)](
            inv_buf, first, L, K, steps, BLOCK_J=bj, num_warps=1
        )

    # ---- stage 4: materialize out ----------------------------------------
    out_shape = list(shape)
    out_shape[d] = K
    if identity:
        out = spec
    else:
        out = torch.empty(out_shape, dtype=x.dtype, device=dev)
    if K > 0 and M > 0 and not identity:
        # Amortize the dependent first[] load and the CTA launch over a large
        # per-CTA byte span, while keeping at least ~16 CTAs when K allows.
        bm = min(triton.next_power_of_2(M), _MAX_TILE)
        bj = min(triton.next_power_of_2(K), max(1, 8192 // bm), max(1, K // 16))
        bj = 1 << (max(1, bj).bit_length() - 1)
        _gather_kernel[(triton.cdiv(K, bj),)](
            x,
            out,
            first,
            K,
            M,
            inner_size,
            sd,
            S_hi,
            unit,
            inner_size,
            K * inner_size,
            HAS_OUTER=outer_size > 1,
            BLOCK_J=bj,
            BLOCK_M=bm,
            num_warps=4,
        )

    # ---- stage 5: run lengths --------------------------------------------
    if return_counts:
        cnt = torch.empty(K, dtype=torch.int64, device=dev)
        if K > 0:
            cb = min(_MAX_TILE, max(triton.next_power_of_2(K), 1))
            _counts_kernel[(triton.cdiv(K, cb),)](
                first, cnt, K, L, BLOCK=cb, num_warps=4
            )
    else:
        cnt = torch.empty(0, dtype=torch.int64, device=dev)

    inv = inv_buf if return_inverse else torch.empty(0, dtype=torch.int64, device=dev)
    return out, inv, cnt
